theory.markdown:
Uma migração é um par de funções: `up` (aplica a mudança) e `down` (desfaz). O runner guarda a versão atual numa tabela `schema_migrations` e aplica as migrações EM ORDEM, das antigas para as novas. Reverter roda o `down` na ordem INVERSA — desfazer a mais nova primeiro, como tirar pratos de uma pilha.

Exemplo de migração com `node:sqlite`:

```js
const migracoes = [
  {
    versao: 1,
    up(db) {
      db.exec(`CREATE TABLE pacientes (
        id INTEGER PRIMARY KEY,
        nome TEXT NOT NULL
      )`);
    },
    down(db) {
      db.exec('DROP TABLE pacientes');
    },
  },
  {
    versao: 2,
    up(db) {
      db.exec('ALTER TABLE pacientes ADD COLUMN telefone TEXT');
    },
    down(db) {
      db.exec('ALTER TABLE pacientes DROP COLUMN telefone');
    },
  },
];
```

E o coração do runner: cada `up` que roda é registrado na tabela de versões — assim, da próxima vez, o runner sabe o que já foi aplicado e só aplica o que falta.

code.code:
import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('clinica.db');

// Tabela de controle: guarda as versões de migração já aplicadas
db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (
  versao INTEGER PRIMARY KEY
)`);

// As migrações do banco, em ordem de versão
const migracoes = [
  {
    versao: 1,
    up(db) {
      db.exec(`CREATE TABLE pacientes (
        id INTEGER PRIMARY KEY,
        nome TEXT NOT NULL
      )`);
    },
    down(db) {
      db.exec('DROP TABLE pacientes');
    },
  },
  {
    versao: 2,
    up(db) {
      db.exec('ALTER TABLE pacientes ADD COLUMN telefone TEXT');
    },
    down(db) {
      db.exec('ALTER TABLE pacientes DROP COLUMN telefone');
    },
  },
];

// Aplicar: roda o up de cada migração entre a versão atual e o alvo,
// e registra cada versão aplicada — na próxima rodada, só o que falta.
function aplicarAte(db, migracoes, alvo) {
  const linha = db.prepare('SELECT MAX(versao) AS v FROM schema_migrations').get();
  const versaoAtual = linha.v ?? 0;
  const registrar = db.prepare('INSERT INTO schema_migrations (versao) VALUES (?)');
  for (const migracao of migracoes) {
    if (migracao.versao > versaoAtual && migracao.versao <= alvo) {
      migracao.up(db);
      registrar.run(migracao.versao);
    }
  }
}

// Reverter: desfaz do mais novo para o mais antigo (pilha), até o alvo.
function reverterAte(db, migracoes, alvo) {
  const linha = db.prepare('SELECT MAX(versao) AS v FROM schema_migrations').get();
  const versaoAtual = linha.v ?? 0;
  const remover = db.prepare('DELETE FROM schema_migrations WHERE versao = ?');
  for (const migracao of [...migracoes].reverse()) {
    if (migracao.versao <= versaoAtual && migracao.versao > alvo) {
      migracao.down(db);
      remover.run(migracao.versao);
    }
  }
}

aplicarAte(db, migracoes, 2);  // sobe para a versão 2 (cria tabela + telefone)
reverterAte(db, migracoes, 1); // volta para a 1 (telefone some)

import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('clinica.db');

db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (
  versao INTEGER PRIMARY KEY
)`);

// Versão 1 — o começo: tabela básica de pacientes.
const migracoes = [
  {
    versao: 1,
    up(db) {
      db.exec(`CREATE TABLE pacientes (
        id INTEGER PRIMARY KEY,
        nome TEXT NOT NULL
      )`);
    },
    down(db) {
      db.exec('DROP TABLE pacientes');
    },
  },
  // Versão 2 — o pedido novo: coluna telefone.
  // O up adiciona; o down remove (o "desenho do como era antes").
  {
    versao: 2,
    up(db) {
      db.exec('ALTER TABLE pacientes ADD COLUMN telefone TEXT');
    },
    down(db) {
      db.exec('ALTER TABLE pacientes DROP COLUMN telefone');
    },
  },
];

function aplicarAte(db, migracoes, alvo) {
  const linha = db.prepare('SELECT MAX(versao) AS v FROM schema_migrations').get();
  const atual = linha.v ?? 0;
  const registrar = db.prepare('INSERT INTO schema_migrations (versao) VALUES (?)');
  for (const migracao of migracoes) {
    if (migracao.versao > atual && migracao.versao <= alvo) {
      migracao.up(db);
      registrar.run(migracao.versao);
    }
  }
}

function reverterAte(db, migracoes, alvo) {
  const linha = db.prepare('SELECT MAX(versao) AS v FROM schema_migrations').get();
  const atual = linha.v ?? 0;
  const remover = db.prepare('DELETE FROM schema_migrations WHERE versao = ?');
  for (const migracao of [...migracoes].reverse()) {
    if (migracao.versao <= atual && migracao.versao > alvo) {
      migracao.down(db);
      remover.run(migracao.versao);
    }
  }
}

// Passo 1: sobe para a versão 2 — cria a tabela e adiciona o telefone
aplicarAte(db, migracoes, 2);

// Passo 2: conferência — o schema tem a coluna nova?
const colunas = db.prepare(
  "SELECT name FROM pragma_table_info('pacientes')",
).all();
console.log(colunas.map((c) => c.name));
// [ 'id', 'nome', 'telefone' ]

// Passo 3: o negócio mudou de ideia — volta para a versão 1.
// O down remove a coluna; o banco fica EXATAMENTE como na versão 1.
reverterAte(db, migracoes, 1);
console.log(db.prepare(
  "SELECT name FROM pragma_table_info('pacientes')",
).all().map((c) => c.name));
// [ 'id', 'nome' ]
